-- Migration: Load career_stage_courses_direct_links_v2 data
-- Adds new columns, creates missing learning paths/stages, and loads v2 courses.

-- 1. Add new columns to courses, learning_paths, and stages tables (idempotent)
ALTER TABLE learning_paths ADD COLUMN IF NOT EXISTS career_identifier VARCHAR(255) UNIQUE;
ALTER TABLE stages ADD COLUMN IF NOT EXISTS stage_identifier VARCHAR(255) UNIQUE;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS course_identifier VARCHAR(255) UNIQUE;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS source_code VARCHAR(100);
ALTER TABLE courses ADD COLUMN IF NOT EXISTS source_name VARCHAR(255);
ALTER TABLE courses ADD COLUMN IF NOT EXISTS cost_type VARCHAR(255);
ALTER TABLE courses ADD COLUMN IF NOT EXISTS notes TEXT;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS provider TEXT;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS page_type TEXT;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS level TEXT;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS direct_link_note TEXT;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS relevance_reason TEXT;

-- 2. Drop old course data (the v1 generated search URLs)
DELETE FROM courses;

-- 3. Create temp table matching v2 SQL structure
DROP TABLE IF EXISTS tmp_v2_courses;
CREATE TEMP TABLE tmp_v2_courses (
    career_identifier TEXT NOT NULL,
    career_name TEXT NOT NULL,
    stage_no TEXT NOT NULL,
    stage_id TEXT NOT NULL,
    stage_name TEXT NOT NULL,
    sort_order TEXT NOT NULL,
    course_identifier TEXT NOT NULL,
    course_title TEXT NOT NULL,
    subtitle_th TEXT,
    provider TEXT,
    source_code TEXT,
    source_name TEXT,
    cost_model TEXT,
    page_type TEXT,
    level TEXT,
    direct_course_url TEXT,
    direct_link_note TEXT,
    relevance_reason TEXT
);

-- 4. Load v2 data into temp table

-- 5. Create learning_paths for all careers in v2 data
UPDATE learning_paths SET career_identifier = 'data_scientist' WHERE career_name = 'Data Scientist' AND career_identifier IS NULL;

SELECT
    gen_random_uuid(),
    career_identifier,
    career_name,
    'Learning path with 6 stages for ' || career_name,
    MAX(CAST(stage_no AS INTEGER))
FROM tmp_v2_courses
GROUP BY career_identifier, career_name
ON CONFLICT (career_identifier) DO UPDATE SET
    career_name = EXCLUDED.career_name,
    description = EXCLUDED.description,
    total_stages = EXCLUDED.total_stages,
    updated_at = NOW();

-- 6. Create stages for all careers in v2 data
WITH seed_stages AS (
    SELECT DISTINCT
        career_identifier,
        career_name,
        CAST(stage_no AS INTEGER) AS stage_number,
        career_identifier || '_stage_' || stage_no AS stage_identifier,
        stage_name
    FROM tmp_v2_courses
)
    id, learning_path_id, stage_number, stage_identifier, title, subtitle,
    position_top, position_left, position_right, position_bottom, position_transform
)
SELECT
    gen_random_uuid(),
    lp.id,
    ss.stage_number,
    ss.stage_identifier,
    ss.stage_name,
    CASE ss.stage_number
        WHEN 1 THEN 'Start with core foundations'
        WHEN 2 THEN 'Build core knowledge'
        WHEN 3 THEN 'Practice essential job skills'
        WHEN 4 THEN 'Deepen specialized skills'
        WHEN 5 THEN 'Create portfolio work'
        WHEN 6 THEN 'Prepare for career launch'
        ELSE ss.stage_name
    END,
    CASE ss.stage_number WHEN 1 THEN '1%' WHEN 2 THEN '17%' WHEN 3 THEN '26%' WHEN 4 THEN '38%' ELSE NULL END,
    CASE ss.stage_number WHEN 1 THEN '62%' WHEN 4 THEN '23%' WHEN 6 THEN '25%' ELSE NULL END,
    CASE ss.stage_number WHEN 2 THEN '55%' WHEN 3 THEN '15%' WHEN 5 THEN '23%' ELSE NULL END,
    CASE ss.stage_number WHEN 5 THEN '33%' WHEN 6 THEN '3%' ELSE NULL END,
    CASE ss.stage_number WHEN 1 THEN 'translateX(-50%)' ELSE NULL END
FROM seed_stages ss
JOIN learning_paths lp ON lp.career_identifier = ss.career_identifier
ON CONFLICT (learning_path_id, stage_number) DO UPDATE SET
    stage_identifier = EXCLUDED.stage_identifier,
    title = EXCLUDED.title,
    subtitle = EXCLUDED.subtitle,
    position_top = EXCLUDED.position_top,
    position_left = EXCLUDED.position_left,
    position_right = EXCLUDED.position_right,
    position_bottom = EXCLUDED.position_bottom,
    position_transform = EXCLUDED.position_transform,
    updated_at = NOW();

-- 7. Normalize from temp table into courses
    id, stage_id, course_identifier, title, subtitle,
    source_code, source_name, cost_type, url, sort_order,
    notes, provider, page_type, level, direct_link_note, relevance_reason
)
SELECT DISTINCT ON (v.course_identifier)
    gen_random_uuid(), s.id, v.course_identifier, v.course_title,
    COALESCE(v.subtitle_th, ''), v.source_code, v.source_name,
    v.cost_model, v.direct_course_url, CAST(v.sort_order AS INTEGER),
    NULL, v.provider, v.page_type, v.level, v.direct_link_note, v.relevance_reason
FROM tmp_v2_courses v
JOIN learning_paths lp ON lp.career_identifier = v.career_identifier
JOIN stages s ON s.learning_path_id = lp.id AND s.stage_number = CAST(v.stage_no AS INTEGER)
ON CONFLICT (course_identifier) DO UPDATE SET
    stage_id = EXCLUDED.stage_id, title = EXCLUDED.title,
    subtitle = EXCLUDED.subtitle, source_code = EXCLUDED.source_code,
    source_name = EXCLUDED.source_name, cost_type = EXCLUDED.cost_type,
    url = EXCLUDED.url, sort_order = EXCLUDED.sort_order,
    provider = EXCLUDED.provider, page_type = EXCLUDED.page_type,
    level = EXCLUDED.level, direct_link_note = EXCLUDED.direct_link_note,
    relevance_reason = EXCLUDED.relevance_reason, updated_at = NOW();

DROP TABLE IF EXISTS tmp_v2_courses;
